#include <vector>
#include <algorithm>
using namespace std;
class Solution {vector<vector<pair<int,int> > >g;vector<vector<int> >up,cnt;vector<int>dep;void dfs(int x,int p){for(auto e:g[x])if(e.first!=p){dep[e.first]=dep[x]+1;up[0][e.first]=x;cnt[0][e.first]=e.second;dfs(e.first,x);}}int lift(int x,int d,vector<int>&c){for(int j=0;d;d>>=1,++j)if(d&1){c[j]+=cnt[j][x];x=up[j][x];}return x;}public:vector<int> minOperationsQueries(int n,vector<vector<int>>&edges,vector<vector<int>>&queries){g.assign(n,{});for(auto&e:edges)g[e[0]].push_back(make_pair(e[1],e[2])),g[e[1]].push_back(make_pair(e[0],e[2]));int B=18;up.assign(B,vector<int>(n));cnt.assign(B,vector<int>(n));dep.assign(n,0);dfs(0,-1);for(int j=1;j<B;j++)for(int i=0;i<n;i++)up[j][i]=up[j-1][up[j-1][i]],cnt[j][i]=cnt[j-1][i]+cnt[j-1][up[j-1][i]];vector<int>r;for(auto&q:queries){int a=q[0],b=q[1];vector<int>ca(B),cb(B);if(dep[a]<dep[b])swap(a,b),swap(ca,cb);a=lift(a,dep[a]-dep[b],ca);if(a!=b){for(int j=B-1;j>=0;j--)if(up[j][a]!=up[j][b]){ca[j]+=cnt[j][a];cb[j]+=cnt[j][b];a=up[j][a];b=up[j][b];}ca[0]+=cnt[0][a];cb[0]+=cnt[0][b];}int z=0,m=0;for(int x:ca)z+=x,m=max(m,x);for(int x:cb)z+=x,m=max(m,x);r.push_back(z-m);}return r;}};
